head.script:
/*
 * WAEA-1429 spinner setProperty("readOnly") 시 readOnly 옵션·내부 입력창 동기화 확인 샘플
 * 요건 확인 버전: 11월정기 1694R (6.0_0.1694R.20261106.105848) PASS 확인 후 자동화 편입
 * - spn_a : readOnly 미지정 → setProperty("readOnly", true/false) 반복
 * - spn_b : inputReadOnly="true" → setProperty true → false (해제 후에도 입력창은 읽기 전용 유지, 버튼은 동작)
 * - spn_c : readOnly="true" 로 생성 → setProperty false 해제 → true 재잠금
 * 결과 노출: 화면 tbx_st_a/b/c, scwin.getState("spn_a") 반환 문자열
 *   형식 "value=<값>|readOnly=<getReadOnly()>|input=<입력창 readOnly>|change=<onviewchange 횟수>"
 */
scwin.changeCnt = { spn_a: 0, spn_b: 0, spn_c: 0 };

scwin.onpageload = function () {
    scwin.refreshAll();
};

scwin.getState = function (id) {
    var c = $p.getComponentById(id);
    var inp = document.getElementById(c.id + "___input");
    return "value=" + c.getValue()
        + "|readOnly=" + c.getReadOnly()
        + "|input=" + (inp ? inp.readOnly : "-")
        + "|change=" + scwin.changeCnt[id];
};

scwin.refresh = function (id) {
    var key = id.substring(id.length - 1);
    $p.getComponentById("tbx_st_" + key).setValue(scwin.getState(id));
};

scwin.refreshAll = function () {
    scwin.refresh("spn_a");
    scwin.refresh("spn_b");
    scwin.refresh("spn_c");
};

scwin.sp = function (id, v) {
    $p.getComponentById(id).setProperty("readOnly", v);
    scwin.refresh(id);
};

scwin.onchange = function (id) {
    scwin.changeCnt[id]++;
    scwin.refresh(id);
};

scwin.btn_a_t_onclick = function () { scwin.sp("spn_a", true); };
scwin.btn_a_f_onclick = function () { scwin.sp("spn_a", false); };
scwin.btn_b_t_onclick = function () { scwin.sp("spn_b", true); };
scwin.btn_b_f_onclick = function () { scwin.sp("spn_b", false); };
scwin.btn_c_t_onclick = function () { scwin.sp("spn_c", true); };
scwin.btn_c_f_onclick = function () { scwin.sp("spn_c", false); };
scwin.btn_refresh_onclick = function () { scwin.refreshAll(); };

scwin.spn_a_onviewchange = function (info) { scwin.onchange("spn_a"); };
scwin.spn_b_onviewchange = function (info) { scwin.onchange("spn_b"); };
scwin.spn_c_onviewchange = function (info) { scwin.onchange("spn_c"); };
